import math

class CountMinSketch:
    def __init__(self, epsilon=1e-3, delta=1e-5):
        self.w = math.ceil(math.e / epsilon)
        self.d = math.ceil(math.log(1 / delta))
        self.table = [[0] * self.w for _ in range(self.d)]
        self.seeds = list(range(self.d))

    def _cells(self, key):
        for i, s in enumerate(self.seeds):
            yield i, hash((s, key)) % self.w

    def add(self, key, count=1):
        for i, j in self._cells(key):
            self.table[i][j] += count

    def estimate(self, key):
        return min(self.table[i][j] for i, j in self._cells(key))

# Sketches merge by elementwise addition, provided the dimensions and hashes match.
# That is what makes them work across shards: each worker keeps its own, and the
# summed sketch is exactly the sketch of the combined stream.
